package.profile_document:
# runx/memory in run.yaml's final shape (run-yaml.md), for the methods in
# memory.md, on the `private` connector (files/connectors/private). A Stage 2
# contract file: the package the build writes is this file, with its modules,
# and a difference is a contract change.
#
# A confirmed write names the entry, inspects its key, decides (`change`
# refuses a handle that isn't current and names the idempotency key and what
# a gate shows), appends at the inspected version, then reads back. A write after an
# ask is guarded on that ask's yes, so with no yes nothing is recorded. A new
# entry's key is the digest of its kind, level and content, so the same words
# name one entry. A correction and a superseding observation are their entry's
# next version, so the store's current entries are memory's current entries.
# A said entry's purpose decides whether it stands as a rule, which its event
# says as `standing`, beside its type, where private lists it apart; any
# entry's `valid_until` is its event's own too, so the store passes over what
# has ended, and every write names `text` and `summary` searchable, so a
# search never matches a confirmation's wording (memory.md, 10 November).
# A new observation instead appends at expected version zero without a prior
# read; the native private driver verifies its event before returning. An
# observation superseding another still inspects its current type and status.
# An operation step's result is read as $steps.<id>.provider_operation.result.
# An output that's a contract names its packet. memory.mjs is a worker with no
# I/O. Only this package writes its streams, and the workspace id comes from
# the runx home ($run.workspace_id, null outside a workspace), never an input.
version: "0.1.1"
minimum_runx: 0.12.0
default_method: index
catalog:
  visibility: public
  category: data
  tags: [memory, context]
shared_inputs:
  level:
    type: string
    enum: [personal, workspace, project, brand]
    description: Whose memory. The person's own, this workspace's, or a project's or brand's in this workspace.
  project:
    type: string
    pattern: "^[A-Za-z0-9][A-Za-z0-9._-]*$"
    maxLength: 64
    optional: true
    description: The project, when level is project. Missing there is a visible missing input, never a default.
  brand:
    type: string
    pattern: "^[A-Za-z0-9][A-Za-z0-9._-]*$"
    maxLength: 64
    optional: true
    description: The brand, when level is brand. Missing there is a visible missing input, never a default.
  levels:
    type: array
    minItems: 1
    maxItems: 8
    description: The levels to read. Streams the run's authority doesn't reach are passed over, never an error.
    items:
      type: object
      additionalProperties: false
      required: [level]
      properties:
        level: { enum: [personal, workspace, project, brand] }
        project: { type: string, pattern: "^[A-Za-z0-9][A-Za-z0-9._-]*$", maxLength: 64 }
        brand: { type: string, pattern: "^[A-Za-z0-9][A-Za-z0-9._-]*$", maxLength: 64 }
  text:
    type: string
    minLength: 1
    maxLength: 4000
    description: The words, exactly.
  summary:
    type: string
    minLength: 1
    maxLength: 120
    pattern: "^[^\r\n]+$"
    description: The line the index shows for the entry, written for recall, a cue to read it, on one line of at most 120 characters.
  purpose:
    type: string
    enum: [mandate, procedure, confirmed_memory]
    description: What the person's words are to a turn. A mandate or a procedure stands as a rule, in every index whatever its age. confirmed_memory is something they told you.
  valid_until:
    type: string
    format: date
    optional: true
    description: The last date the entry is true. Once it has passed, the index leaves it out, and history, search and read keep it.
  date:
    type: string
    format: date
    description: The fact's own date, never when it was stored, so a date from a model or a page can't reorder anything (D35).
  sources:
    type: array
    minItems: 1
    maxItems: 16
    items: { type: string, minLength: 1, maxLength: 2048 }
    description: Where it came from.
  handle:
    type: string
    pattern: "^memory:[^#]+#[^#]+@[0-9]+$"
    maxLength: 512
    description: One entry at one version, memory:<stream>#<key>@<version>.
methods:
  remember:
    description: Keep the person's exact words, with the line the index shows for them and their purpose, once the person confirms them. Without supersedes, it first looks for current entries on their stream that match the words, and when any does it keeps nothing and returns them, so the writer decides with them in view. Naming the entry it supersedes makes it a correction of that entry, with the correction's own gate. Nothing is recorded without the confirmation.
    inputs:
      level: {}
      project: {}
      brand: {}
      text: {}
      summary: {}
      purpose: {}
      date: {}
      valid_until: {}
      sources: {}
      supersedes: { type: string, pattern: "^(none|memory:said:[^#]+#[^#]+@[0-9]+)$", maxLength: 512, optional: true, description: "The entry these words replace, at its current version, which makes this its correction, or none. Without it, words that match a current entry are returned rather than kept." }
    examples:
      - { level: personal, text: I write in Australian English., summary: I write in Australian English., purpose: confirmed_memory, date: 2026-11-08, sources: [conversation], supersedes: none }
    result_from: [likely, corrected, handle]
    steps:
      - id: entry
        tool: { module: memory.mjs, export: newEntry }
        inputs: { kind: said, level: $input.level, project: $input.project, brand: $input.brand, workspace_id: $run.workspace_id, text: $input.text, date: $input.date, sources: $input.sources, supersedes: $input.supersedes }
        outputs:
          stream: { type: string }
          key: { type: string }
          version: { type: integer }
      - id: likely
        when: { value: $steps.entry.version, equals: 0 }
        script: { module: memory.mjs, export: likely }
        inputs: { entry: $steps.entry, kind: said, text: $input.text, supersedes: $input.supersedes, method: remember }
        calls:
          operations: [private/keys.search]
        max_calls: 1
        effects: none
        outputs:
          matches: { type: array, packet: runx/memory.entries.v1, description: "The current entries on the stream whose text best matches the words, best first. When any matches, nothing is kept." }
      - id: corrected
        when: { value: $steps.entry.version, not_equals: 0 }
        skill: .#correct
        inputs: { handle: $input.supersedes, text: $input.text, summary: $input.summary, purpose: $input.purpose, date: $input.date, valid_until: $input.valid_until, sources: $input.sources }
        outputs:
          handle: { type: string }
      - id: current
        when: { value: $steps.likely.matches, equals: [] }
        operation: private/key.inspect
        inputs: { stream: $steps.entry.stream, key: $steps.entry.key }
      - id: change
        when: { value: $steps.likely.matches, equals: [] }
        tool: { module: memory.mjs, export: change }
        inputs: { entry: $steps.entry, current: $steps.current.provider_operation.result, type: memory.remembered, data: { text: $input.text, summary: $input.summary, purpose: $input.purpose, date: $input.date, sources: $input.sources, confirmation: CONF }, valid_until: $input.valid_until }
        outputs:
          reason: { type: string }
          idempotency_key: { type: string }
          expected_version: { type: integer }
          standing: { type: boolean }
      - id: confirm
        when: { value: $steps.likely.matches, equals: [] }
        ask: { gate: memory.remember, reason: $steps.change.reason, type: person_words }
        inputs: { quote: $input.text, summary: $input.summary, purpose: $input.purpose, date: $input.date, valid_until: $input.valid_until, sources: $input.sources, stream: $steps.entry.stream }
      - id: append
        when: { value: $steps.likely.matches, equals: [] }
        operation: private/events.append
        guard:
          - { value: $steps.confirm.approval_decision.approved, equals: true }
        inputs:
          stream: $steps.entry.stream
          key: $steps.entry.key
          expected_version: $steps.current.provider_operation.result.version
          type: memory.remembered
          data: { text: $input.text, summary: $input.summary, purpose: $input.purpose, date: $input.date, sources: $input.sources, confirmation: $steps.confirm }
          searchable: [text, summary]
          standing: $steps.change.standing
          valid_until: $input.valid_until
        idempotency_key: $steps.change.idempotency_key
      - id: readback
        when: { value: $steps.likely.matches, equals: [] }
        operation: private/key.inspect
        confirms: append
        inputs: { stream: $steps.entry.stream, key: $steps.entry.key }
      - id: handle
        when: { value: $steps.likely.matches, equals: [] }
        tool: { module: memory.mjs, export: entryHandle }
        inputs: { entry: $steps.entry, appended: $steps.append.provider_operation.result, readback: $steps.readback.provider_operation.result }
        outputs:
          handle: { type: string }
  correct:
    description: Replace the person's words with corrected words, with their line and purpose, as the entry's next version. Its earlier words stay in its history.
    inputs: { handle: {}, text: {}, summary: {}, purpose: {}, date: {}, valid_until: {}, sources: {} }
    steps:
      - id: entry
        tool: { module: memory.mjs, export: parseHandle }
        inputs: { handle: $input.handle, kind: said }
        outputs:
          stream: { type: string }
          key: { type: string }
          version: { type: integer }
          after_version: { type: integer }
      - id: current
        operation: private/key.inspect
        inputs: { stream: $steps.entry.stream, key: $steps.entry.key }
      - id: change
        tool: { module: memory.mjs, export: change }
        inputs: { entry: $steps.entry, current: $steps.current.provider_operation.result, type: memory.corrected, data: { text: $input.text, summary: $input.summary, purpose: $input.purpose, date: $input.date, sources: $input.sources, confirmation: CONF }, valid_until: $input.valid_until }
        outputs:
          reason: { type: string }
          idempotency_key: { type: string }
          expected_version: { type: integer }
          standing: { type: boolean }
      - id: confirm
        ask: { gate: memory.correct, reason: $steps.change.reason }
        inputs: { handle: $input.handle, version: $steps.current.provider_operation.result.version, text: $input.text, summary: $input.summary, purpose: $input.purpose, date: $input.date, valid_until: $input.valid_until, sources: $input.sources }
      - id: append
        operation: private/events.append
        guard:
          - { value: $steps.confirm.approval_decision.approved, equals: true }
        inputs:
          stream: $steps.entry.stream
          key: $steps.entry.key
          expected_version: $steps.current.provider_operation.result.version
          type: memory.corrected
          data: { text: $input.text, summary: $input.summary, purpose: $input.purpose, date: $input.date, sources: $input.sources, confirmation: $steps.confirm }
          searchable: [text, summary]
          standing: $steps.change.standing
          valid_until: $input.valid_until
        idempotency_key: $steps.change.idempotency_key
      - id: readback
        operation: private/key.inspect
        confirms: append
        inputs: { stream: $steps.entry.stream, key: $steps.entry.key }
      - id: handle
        tool: { module: memory.mjs, export: entryHandle }
        inputs: { entry: $steps.entry, appended: $steps.append.provider_operation.result, readback: $steps.readback.provider_operation.result }
        outputs:
          handle: { type: string }
  disable:
    description: Stop an entry applying. The record keeps it, and reading history still reaches it.
    inputs: 
      handle: {}
      reason: { type: string, minLength: 1, maxLength: 1000, description: Why it stops applying. }
    steps:
      - id: entry
        tool: { module: memory.mjs, export: parseHandle }
        inputs: { handle: $input.handle }
        outputs:
          stream: { type: string }
          key: { type: string }
          version: { type: integer }
          after_version: { type: integer }
      - id: current
        operation: private/key.inspect
        inputs: { stream: $steps.entry.stream, key: $steps.entry.key }
      - id: change
        tool: { module: memory.mjs, export: change }
        inputs: { entry: $steps.entry, current: $steps.current.provider_operation.result, type: memory.disabled, data: { reason: $input.reason, confirmation: CONF } }
        outputs:
          reason: { type: string }
          idempotency_key: { type: string }
          expected_version: { type: integer }
      - id: confirm
        ask: { gate: memory.disable, reason: $steps.change.reason }
        inputs: { handle: $input.handle, version: $steps.current.provider_operation.result.version, reason: $input.reason }
      - id: append
        operation: private/events.append
        guard:
          - { value: $steps.confirm.approval_decision.approved, equals: true }
        inputs:
          stream: $steps.entry.stream
          key: $steps.entry.key
          expected_version: $steps.current.provider_operation.result.version
          type: memory.disabled
          data: { reason: $input.reason, confirmation: $steps.confirm }
        idempotency_key: $steps.change.idempotency_key
      - id: readback
        operation: private/key.inspect
        confirms: append
        inputs: { stream: $steps.entry.stream, key: $steps.entry.key }
      - id: handle
        tool: { module: memory.mjs, export: entryHandle }
        inputs: { entry: $steps.entry, appended: $steps.append.provider_operation.result, readback: $steps.readback.provider_operation.result }
        outputs:
          handle: { type: string }
  observe:
    description: Keep what an agent found, with its date, sources and the line the index shows for it. Without supersedes, it first looks for current observations on its stream that match it, and when any does it keeps nothing and returns them, so the writer decides with them in view. Naming the observation it supersedes makes this that entry's next version, and the one it replaces stays in the entry's history. Never promoted into an instruction or a confirmed memory.
    inputs: 
      level: {}
      project: {}
      brand: {}
      text: {}
      summary: {}
      date: {}
      valid_until: {}
      sources: {}
      supersedes: { type: string, pattern: "^(none|memory:observed:[^#]+#[^#]+@[0-9]+)$", maxLength: 512, optional: true, description: "The observation this one replaces, at its current version, or none. Without it, an observation that matches a current one is returned rather than kept." }
    result_from: [likely, handle]
    steps:
      - id: entry
        tool: { module: memory.mjs, export: newEntry }
        inputs: { kind: observed, level: $input.level, project: $input.project, brand: $input.brand, workspace_id: $run.workspace_id, text: $input.text, date: $input.date, sources: $input.sources, supersedes: $input.supersedes }
        outputs:
          stream: { type: string }
          key: { type: string }
          version: { type: integer }
      - id: likely
        script: { module: memory.mjs, export: likely }
        inputs: { entry: $steps.entry, kind: observed, text: $input.text, supersedes: $input.supersedes, method: observe }
        calls:
          operations: [private/keys.search]
        max_calls: 1
        effects: none
        outputs:
          matches: { type: array, packet: runx/memory.entries.v1, description: "The current observations on the stream whose text best matches this one, best first. When any matches, nothing is kept." }
      - id: change
        when: { value: $steps.likely.matches, equals: [] }
        script: { module: memory.mjs, export: observationChange }
        inputs: { entry: $steps.entry, data: { text: $input.text, summary: $input.summary, date: $input.date, sources: $input.sources }, valid_until: $input.valid_until }
        calls:
          operations: [private/key.inspect]
        max_calls: 1
        effects: none
        outputs:
          reason: { type: string }
          idempotency_key: { type: string }
          expected_version: { type: integer }
      - id: append
        when: { value: $steps.likely.matches, equals: [] }
        operation: private/events.append
        inputs:
          stream: $steps.entry.stream
          key: $steps.entry.key
          expected_version: $steps.change.expected_version
          type: memory.observed
          data: { text: $input.text, summary: $input.summary, date: $input.date, sources: $input.sources }
          searchable: [text, summary]
          valid_until: $input.valid_until
        idempotency_key: $steps.change.idempotency_key
      - id: handle
        when: { value: $steps.likely.matches, equals: [] }
        tool: { module: memory.mjs, export: entryHandle }
        inputs: { entry: $steps.entry, appended: $steps.append.provider_operation.result }
        outputs:
          handle: { type: string }
  index:
    description: A bounded index of the entries the run may read, for a turn's context, as one entry per stream and purpose, its lines under a header, memory:<stream>. Each line is <key>@<version> <date> <summary>, its key the shortest start of the entry's key, at least 8 characters, that no other line of its stream shares, which read takes with the header as a short handle. The person's standing rules first, every one, oldest first, then facts, the person's words before observations, newest first or the ones that match the focus first. Every line shows its summary, facts fill the room the rules leave whole and the first that doesn't fit ends them, and a rule's line never goes, only its summary, when the rules alone pass the limit. An entry whose end date has passed is left out.
    inputs:
      levels: {}
      max_characters: { type: integer, minimum: 256, maximum: 32768, default: 4096, optional: true, description: The most characters the index may hold. }
      focus: { type: string, minLength: 1, maxLength: 512, optional: true, description: "What the turn is about to do. The facts that match it come first, ranked by search, and the rest follow newest first." }
    examples:
      - { levels: [{ level: personal }] }
    steps:
      - id: index
        script: { module: memory.mjs, export: index }
        inputs: { levels: $input.levels, max_characters: $input.max_characters, focus: $input.focus, workspace_id: $run.workspace_id }
        calls:
          operations: [private/keys.list, private/keys.search]
          tools: [data.digest]
        max_calls: 96
        effects: none
        outputs:
          entries: { type: array, packet: runx/memory.entries.v1, description: "runx.context_entry.v1 values, one per stream and purpose: its header and lines as its summary, its entries whole as its data." }
          entries_omitted: { type: boolean, description: "Some entries didn't fit, and search and read reach them." }
          over_budget: { type: boolean, description: "The standing rules alone pass max_characters whole, so no fact shows and the rules' summaries go, newest first, until the index fits or none is left: every rule's line shows, because a rule the turn can't see is one it can't follow." }
  search:
    description: Ranked matches among the current entries of the streams the run may read. Reading history is explicit, with read.
    inputs:
      levels: {}
      query: { type: string, minLength: 1, maxLength: 512 }
      limit: { type: integer, minimum: 1, maximum: 50, default: 10, optional: true }
    steps:
      - id: search
        script: { module: memory.mjs, export: search }
        inputs: { levels: $input.levels, query: $input.query, limit: $input.limit, workspace_id: $run.workspace_id }
        calls:
          operations: [private/keys.search]
        max_calls: 16
        effects: none
        outputs:
          entries: { type: array, packet: runx/memory.entries.v1, description: "runx.context_entry.v1 values, best match first." }
  read:
    description: One entry by handle, at the version the handle names, whether or not it's still current. A short handle, an index line's header and key, is resolved within its stream, and one whose key begins no entry's, or more than one, is refused with the full handles it could mean.
    inputs: { handle: {} }
    steps:
      - id: entry
        tool: { module: memory.mjs, export: parseHandle }
        inputs: { handle: $input.handle, short: true }
        outputs:
          stream: { type: string }
          key: { type: string }
          version: { type: integer }
          after_version: { type: integer }
      - id: resolved
        script: { module: memory.mjs, export: resolveHandle }
        inputs: { entry: $steps.entry }
        calls:
          operations: [private/keys.list]
        max_calls: 1
        effects: none
        outputs:
          handle: { type: string }
          stream: { type: string }
          key: { type: string }
          after_version: { type: integer }
      - id: read
        operation: private/events.read
        inputs: { stream: $steps.resolved.stream, key: $steps.resolved.key, after_version: $steps.resolved.after_version, limit: 1 }
      - id: context
        tool: { module: memory.mjs, export: contextEntry }
        inputs: { handle: $steps.resolved.handle, read: $steps.read.provider_operation.result }
        outputs:
          entry: { type: object, packet: runx.context_entry.v1 }

package_files.content:
// memory's horizon evaluation at one size and phase: each of the phase's
// cases in evals/horizon.json asked of the routine, `repeats` times, each
// attempt judged by `grade`, a deterministic step whose verdict the runtime
// names the evaluator of, and decided by the one rule (`verdict.decide`).
// The history it asks over is laid down by its test, in a fresh home for
// each size, with the run's clock pinned. Only the record says what an
// attempt did: its turn's model, host and usage, how it ended, and what it
// kept.

const ROUTINE = "../routine";
const ROUTINES = [ROUTINE, `${ROUTINE}#draft`];
const SEARCH = "../..#search";

export async function sweep(ctx, { subject, memory, phase, case_id, repeats, focus }) {
  const judged = { ref: memory, revision: subject.inspect.package_digest };
  const horizon = await readJson(ctx, `${memory}/evals/horizon.json`);
  const cases = [];
  for (const kase of horizon.cases.filter((candidate) => candidate.phase === phase && (case_id === undefined || candidate.id === case_id))) {
    const { criteria } = await ctx.tool("verdict.criteria", { criteria: checks(kase) });
    const set = await ctx.read(criteria);
    cases.push({ kase, criteria: set, criteria_set: { ref: `${memory}/evals/horizon.json#${kase.id}`, revision: set.revision } });
  }
  if (cases.length === 0) throw new Error(`phase ${phase} has no case ${case_id ?? "to run"}`);
  const now = ctx.now();
  const attempts = [];
  for (const item of cases) {
    const question = dated(item.kase.question, now);
    for (let attempt = 0; attempt < repeats; attempt += 1) {
      const inputs = { question, ...(focus ? { focus: question } : {}) };
      const method = item.kase.method === undefined ? ROUTINE : `${ROUTINE}#${item.kase.method}`;
      const settled = await settle(ctx.skill(method, inputs));
      attempts.push({ item, settled, kept: await kept(ctx, item.kase) });
    }
  }
  const record = await readRecord(ctx);
  const runs = childRuns(record, ROUTINES, attempts.length);
  for (const [index, attempt] of attempts.entries()) {
    attempt.turn = turnOf(record, runs[index]);
    attempt.receipt_id = sealedIn(record, runs[index]);
    attempt.ending = attempt.settled.status === "fulfilled"
      ? "answered"
      : attempt.settled.message;
    attempt.decision = await judge(ctx, judged, attempt);
  }
  return {
    report: {
      phase,
      focus,
      repeats,
      ...started(record),
      attempts: attempts.map(({ item, turn, ending: end, decision, receipt_id }) => ({
        case: item.kase.id,
        category: item.kase.category,
        ...(item.kase.planted === undefined ? {} : { planted: item.kase.planted }),
        verdict: decision.decision?.verdict ?? null,
        ...(decision.decision?.status === "refused" ? { refused: decision.decision.reason } : {}),
        ending: end,
        model: turn.model,
        host: turn.host,
        usage: turn.usage,
        receipt_id,
      })),
    },
  };
}

/// A case's question with each `{days_ago:N}` as the date N days before the
/// run's clock, as its test laid the history's dates down.
function dated(question, now) {
  return question.replace(/\{days_ago:(\d+)\}/g, (_, days) =>
    new Date(now - Number(days) * 86_400_000).toISOString().slice(0, 10),
  );
}

/// The checks a case is judged against, each a question that must be
/// answered yes, all required.
function checks(kase) {
  const expect = kase.expect;
  const checks = [];
  if (expect.found !== undefined) {
    checks.push({ id: "found", required: true, question: `Does the answer say memory ${expect.found ? "held" : "didn't hold"} the answer?` });
  }
  for (const [index, word] of (expect.says ?? []).entries()) {
    checks.push({ id: `says_${index + 1}`, required: true, question: `Does the answer say "${word}"?` });
  }
  for (const [index, word] of (expect.never ?? []).entries()) {
    checks.push({ id: `never_${index + 1}`, required: true, question: `Does the answer leave out "${word}"?` });
  }
  if (expect.keeps) {
    checks.push({ id: "keeps", required: true, question: `Did the run keep an observation saying ${expect.keeps.says.join(" and ")}?` });
  }
  return checks;
}

/// What memory holds after an attempt that a capture case expects kept: the
/// current observations a search for its words finds. What was kept, never
/// what the turn says it kept.
async function kept(ctx, kase) {
  if (!kase.expect.keeps) return [];
  const { entries } = await ctx.skill(SEARCH, { levels: [{ level: "personal" }], query: kase.expect.keeps.says.join(" ") });
  return entries.filter((entry) => entry.labels.purpose === "observation").map((entry) => entry.data.text);
}

/// One attempt judged by the grade, decided against what this sweep expects
/// judged. A grade the runtime refused answers nothing.
async function judge(ctx, judged, { item, settled, kept: keptTexts }) {
  let verdict;
  try {
    ({ verdict } = await ctx.skill(".#grade", {
      subject: judged,
      criteria_set: item.criteria_set,
      criteria: item.criteria,
      case: item.kase,
      attempt: {
        status: settled.status,
        ...(settled.status === "fulfilled" ? { result: { answer: settled.value.answer, found: settled.value.found } } : {}),
        kept: keptTexts,
      },
    }));
  } catch (rejected) {
    return { decision: { status: "refused", reason: rejected.message } };
  }
  const { decision } = await ctx.tool("verdict.decide", {
    verdict: await ctx.read(verdict),
    subject: judged,
    criteria_ref: item.criteria_set.ref,
    criteria: item.criteria,
  });
  return { decision: await ctx.read(decision) };
}

/// The grade: each check answered from the attempt alone, with no model.
/// An attempt that gave no answer leaves every check inconclusive.
export function grade({ subject, criteria_set, criteria, case: kase, attempt }) {
  const answer = String(attempt.result?.answer ?? "");
  const lowered = answer.toLowerCase();
  const expect = kase.expect;
  const assessments = criteria.criteria.map(({ id }) => {
    if (attempt.status !== "fulfilled") return { verdict: "inconclusive", id, evidence: [] };
    const [kind, number] = id.split("_");
    const met = (holds, expected, actual, where = "the routine's answer") =>
      holds
        ? { verdict: "met", id, evidence: [] }
        : { verdict: "not_met", id, evidence: [], failure: { expected, actual: actual || "nothing", where } };
    switch (kind) {
      case "found":
        return met(attempt.result?.found === expect.found, `found ${expect.found}`, `found ${attempt.result?.found}`);
      case "says": {
        const word = expect.says[Number(number) - 1];
        return met(lowered.includes(word.toLowerCase()), word, answer);
      }
      case "never": {
        const word = expect.never[Number(number) - 1];
        return met(!lowered.includes(word.toLowerCase()), `no "${word}"`, answer);
      }
      case "keeps": {
        const held = attempt.kept.some((text) =>
          expect.keeps.says.every((word) => text.toLowerCase().includes(word.toLowerCase())),
        );
        return met(held, expect.keeps.says.join(" and "), attempt.kept.join(" | "), "memory's observations");
      }
      default:
        throw new Error(`no check is named ${id}`);
    }
  });
  const answers = assessments.map((assessment) => assessment.verdict);
  const verdict = answers.includes("not_met") ? "not_met" : answers.includes("inconclusive") ? "inconclusive" : "met";
  return { verdict: { schema: "runx.verdict.v1", verdict, subject, criteria_set, assessments } };
}

async function settle(call) {
  try {
    return { status: "fulfilled", value: await call };
  } catch (rejected) {
    return { status: "rejected", message: rejected.message };
  }
}

async function readJson(ctx, path) {
  const { file_read } = await ctx.tool("fs.read", { path });
  const read = await ctx.read(file_read);
  if (read.truncated) throw new Error(`${path} is longer than one read`);
  return JSON.parse(read.contents);
}

// This run's record, every page of it.
async function readRecord(ctx) {
  const pages = [];
  let after;
  for (;;) {
    const { run_read } = await ctx.tool("run.read", after === undefined ? {} : { after });
    const page = await ctx.read(run_read);
    pages.push(page);
    if (!page.more) return { run: page.run, events: pages.flatMap((read) => read.events) };
    after = page.cursor;
  }
}

// The child run of each call this run's script made of `host`, in the order
// it made them. A step's calls are on a stream of their own,
// `<run>/<step>@<attempt>`, beside the run's.
function childRuns({ run, events }, hosts, made) {
  const root = run.run_id;
  const calls = new Map();
  for (const { stream, event } of events) {
    if (
      event.kind === "call" &&
      stream === `${root}/${event.step_id}@${event.attempt}` &&
      event.target?.kind === "skill" &&
      hosts.includes(event.target.skill)
    ) {
      calls.set(event.index, `${event.step_id}/${event.index}`);
    }
  }
  const children = new Map(
    events
      .filter(({ event }) => event.kind === "child_started" && event.parent === root)
      .map(({ stream, event }) => [event.step_id, stream]),
  );
  const runs = [...calls.entries()]
    .sort(([left], [right]) => left - right)
    .map(([, position]) => {
      const stream = children.get(position);
      if (stream === undefined) throw new Error(`this run's record holds no child run for its call ${position}`);
      return stream;
    });
  if (runs.length !== made) {
    throw new Error(`this run's record holds ${runs.length} calls of ${hosts.join(" or ")}, and this script made ${made}`);
  }
  return runs;
}

// Whether `stream` is the child run `run`'s, or one of the streams below it.
function within(run, stream) {
  return stream === run || stream.startsWith(`${run}/`);
}

// Where the run ran and what started it, as its start recorded them.
function started({ events }) {
  const start = events.find(({ event }) => event.kind === "started");
  if (start === undefined) throw new Error("this run's record holds no start");
  return { ran_on: start.event.ran_on, implementation: start.event.implementation };
}

// The model that answered the turn in the run `run`, the host that gave its
// answer and what its calls to the model used, as its answer states them:
// from the agent step's event in that run.
function turnOf({ events }, run) {
  const step = events.find(
    ({ stream, event }) => within(run, stream) && event.kind === "step" && (event.host || event.model),
  );
  return { host: step?.event.host ?? null, model: step?.event.model ?? null, usage: step?.event.usage ?? null };
}

// The receipt the run `run` sealed with.
function sealedIn({ events }, run) {
  return events.find(({ stream, event }) => stream === run && event.kind === "sealed")?.event.receipt_id;
}

// Source selection is judgment; date comparison and history traversal use
// admitted memory reads. The recorded clock supplies a current query's date.
export async function selected(ctx, { handle, as_of }) {
  const date = as_of || new Date(ctx.now()).toISOString().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || new Date(date).toISOString().slice(0, 10) !== date) {
    throw new Error("as_of must be a calendar date or empty for the current date");
  }
  const match = /^(memory:[^#]+#[^@]+)@([0-9]+)$/.exec(handle);
  if (!match || !Number.isSafeInteger(Number(match[2]))) throw new Error("select an actual memory handle");
  for (let version = Number(match[2]); version > 0; version -= 1) {
    const result = await ctx.skill("../..#read", { handle: `${match[1]}@${version}` });
    const entry = await ctx.read(result.entry);
    if (entry.data.type === "memory.disabled") return missing();
    if (entry.data.date > date) continue;
    if (entry.data.valid_until && entry.data.valid_until < date) return missing();
    return { answer: entry.data.text, found: true, source: entry };
  }
  return missing();
}

export function missing() {
  return { answer: "No matching memory entry was selected.", found: false };
}

// The model identifies facts, but cannot invent the words, confirmation,
// source or write result. Observation matching and replacement remain memory's.
export async function capture(ctx, { question, observations }) {
  const today = new Date(ctx.now()).toISOString().slice(0, 10);
  for (const { quote } of observations) {
    if (!question.includes(quote) || quote.trim().endsWith("?")) {
      throw new Error("capture an exact factual statement, never the accompanying question");
    }
  }
  for (const observation of observations) {
    const { quote, date, supersedes } = observation;
    const kept = await ctx.skill("../..#observe", {
      level: "personal", text: quote, summary: quote.replace(/[\r\n]+/g, " ").slice(0, 120),
      date: date ?? today, sources: ["conversation"], supersedes,
    });
    if (!kept.handle) throw new Error("memory did not confirm the observation write");
  }
  return { count: observations.length };
}

// runx/memory: a person's words and an agent's observations, kept on
// `private` by level (memory.md). A worker with no I/O: every read and write
// is a step of run.yaml, or a call the index and search scripts make through
// ctx, so a run's record holds everything memory did.

const SCHEMA = "runx.context_entry.v1";
const SKILL = "runx/memory";
/// The most keys one page of a listing or a search asks a stream for.
const MAX_PAGE_KEYS = 100;
/// The most current entries a write is shown that it likely replaces.
const LIKELY_MATCHES = 5;
/// The fewest characters an index line holds, `<key>@<version> <date>`, so a
/// page asks a stream for no more keys than the room left could show.
const SHORTEST_LINE = 21;
/// The fewest hex characters of an entry's key an index line shows.
const SHORTEST_KEY = 8;
/// A short handle's key: the start of an entry's key, as an index line shows
/// it, which `read` resolves within its stream. An entry's own key is 64.
const SHORT_KEY = /^[0-9a-f]{8,63}$/;
/// The most full handles a short handle that could mean more than one names.
const SHORT_MATCHES = 10;
const NAME = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
/// The purposes that make the person's words a standing rule, which every
/// index shows whatever its age.
const STANDING = new Set(["mandate", "procedure"]);
const KINDS = {
  said: {
    types: ["memory.remembered", "memory.corrected"],
    trust: "person_confirmed",
  },
  observed: {
    types: ["memory.observed"],
    trust: "untrusted_evidence",
  },
};

// SHA-256 over a string's UTF-8 bytes, as hex: a worker has no crypto.
const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

function utf8(text) {
  const bytes = [];
  for (const character of text) {
    let point = character.codePointAt(0);
    if (point < 0x80) {
      bytes.push(point);
    } else if (point < 0x800) {
      bytes.push(0xc0 | (point >> 6), 0x80 | (point & 0x3f));
    } else if (point < 0x10000) {
      bytes.push(0xe0 | (point >> 12), 0x80 | ((point >> 6) & 0x3f), 0x80 | (point & 0x3f));
    } else {
      bytes.push(
        0xf0 | (point >> 18),
        0x80 | ((point >> 12) & 0x3f),
        0x80 | ((point >> 6) & 0x3f),
        0x80 | (point & 0x3f),
      );
    }
  }
  return bytes;
}

function sha256(text) {
  const bytes = utf8(text);
  const bits = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let shift = 56; shift >= 0; shift -= 8) {
    bytes.push(shift >= 32 ? Math.floor(bits / 2 ** shift) & 0xff : (bits >>> shift) & 0xff);
  }
  const hash = new Uint32Array([
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ]);
  const words = new Uint32Array(64);
  const rotate = (value, by) => (value >>> by) | (value << (32 - by));
  for (let chunk = 0; chunk < bytes.length; chunk += 64) {
    for (let index = 0; index < 16; index += 1) {
      const at = chunk + index * 4;
      words[index] = (bytes[at] << 24) | (bytes[at + 1] << 16) | (bytes[at + 2] << 8) | bytes[at + 3];
    }
    for (let index = 16; index < 64; index += 1) {
      const low = words[index - 15];
      const high = words[index - 2];
      const s0 = rotate(low, 7) ^ rotate(low, 18) ^ (low >>> 3);
      const s1 = rotate(high, 17) ^ rotate(high, 19) ^ (high >>> 10);
      words[index] = (words[index - 16] + s0 + words[index - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = hash;
    for (let index = 0; index < 64; index += 1) {
      const s1 = rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25);
      const choose = (e & f) ^ (~e & g);
      const first = (h + s1 + choose + K[index] + words[index]) >>> 0;
      const s0 = rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const second = (s0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + first) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (first + second) >>> 0;
    }
    const next = [a, b, c, d, e, f, g, h];
    for (let index = 0; index < 8; index += 1) hash[index] = (hash[index] + next[index]) >>> 0;
  }
  return Array.from(hash, (word) => word.toString(16).padStart(8, "0")).join("");
}

/// The stream a level names for one kind, as memory.md's table names it.
/// A level that needs a workspace, a project or a brand it wasn't given is
/// a visible missing input, never a default.
function streamOf(kind, { level, project, brand, workspace_id: workspace }) {
  const named = (value, what) => {
    if (typeof value !== "string" || !NAME.test(value)) {
      throw new Error(`level ${level} needs ${what}, and none was given`);
    }
    return value;
  };
  switch (level) {
    case "personal":
      return `${kind}:personal`;
    case "workspace":
      return `${kind}:workspace:${named(workspace, "a workspace: this run has no workspace id")}`;
    case "project":
      return `${kind}:project:${named(workspace, "a workspace: this run has no workspace id")}:${named(project, "a project")}`;
    case "brand":
      return `${kind}:brand:${named(workspace, "a workspace: this run has no workspace id")}:${named(brand, "a brand")}`;
    default:
      throw new Error(`level ${level} is none of personal, workspace, project or brand`);
  }
}

/// A memory stream's kind, or nothing when the stream is none of memory's.
function kindOf(stream) {
  const [kind, level, ...rest] = stream.split(":");
  if (!(kind in KINDS)) return undefined;
  const shaped =
    (level === "personal" && rest.length === 0) ||
    (level === "workspace" && rest.length === 1) ||
    ((level === "project" || level === "brand") && rest.length === 2);
  return shaped && rest.every((part) => part.length > 0) ? kind : undefined;
}

function handleOf(stream, key, version) {
  return `memory:${stream}#${key}@${version}`;
}

/// `memory:<stream>#<key>@<version>`, the version the digits after the last
/// `@`, refused unless it names one of memory's streams, of `kind` when one
/// is given. A short handle, whose key is only the start of an entry's, is
/// refused unless `short` says the caller resolves it.
function parsed(handle, kind, { short = false } = {}) {
  const match = /^memory:([^#]+)#([^#]+)@([0-9]+)$/u.exec(handle ?? "");
  if (!match) throw new Error(`${handle} is no memory handle: memory:<stream>#<key>@<version>`);
  const [, stream, key, digits] = match;
  const version = Number(digits);
  const found = kindOf(stream);
  if (!found) throw new Error(`${handle} names ${stream}, which is none of memory's streams`);
  if (kind && found !== kind) throw new Error(`${handle} isn't a ${kind} entry`);
  if (!Number.isSafeInteger(version) || version < 1) {
    throw new Error(`${handle} names version ${digits}, and an entry's versions start at 1`);
  }
  if (!short && SHORT_KEY.test(key)) {
    throw new Error(`${handle} is a short handle, which only read takes: read it for the entry's full handle`);
  }
  return { stream, key, version, kind: found };
}

/// The entry a `said` or `observed` write names: its stream, from its level,
/// and its key. A write that supersedes `none`, or doesn't say, names a new
/// entry, at version 0, whose key is the digest of its kind, level and
/// content, so the same words name one entry. One that supersedes a handle
/// names that entry at its version: an observation's next version, or for
/// the person's words, the entry their correction replaces.
export function newEntry({ kind, level, project, brand, workspace_id, text, date, sources, supersedes }) {
  const stream = streamOf(kind, { level, project, brand, workspace_id });
  if (supersedes !== undefined && supersedes !== "none") {
    const replaced = parsed(supersedes, kind);
    if (replaced.stream !== stream) {
      throw new Error(`${supersedes} is on ${replaced.stream}, not on ${stream}, where this is kept`);
    }
    return { stream, key: replaced.key, version: replaced.version };
  }
  const key = sha256(JSON.stringify(["runx/memory.entry.v1", kind, stream, text, date, sources]));
  return { stream, key, version: 0 };
}

/// What a new entry likely replaces: when its writer didn't say what it
/// supersedes, the current entries on the stream it would be kept on whose
/// text best matches its own, from one search, best first. When the writer
/// said, or nothing matches, there's nothing to decide, and it's kept.
export async function likely(ctx, { entry, kind, text, supersedes, method }) {
  if (supersedes !== undefined) return { matches: [] };
  const found = await resultOf(
    ctx,
    await ctx.operation("private/keys.search", {
      stream: entry.stream,
      query: text,
      types: KINDS[kind].types,
      limit: LIKELY_MATCHES,
    }),
  );
  return {
    matches: (found?.matches ?? []).map(({ key, last_event }) =>
      entryOf({ stream: entry.stream, key, event: last_event, method }),
    ),
  };
}

/// The entry a handle names, at its version, and the version a read of that
/// version reads after. A short handle is refused unless `short` says the
/// caller resolves it, as `read` does.
export function parseHandle({ handle, kind, short = false }) {
  const { stream, key, version } = parsed(handle, kind, { short });
  return { stream, key, version, after_version: version - 1 };
}

/// The entry `read` reads, by its full handle. A short handle's key is the
/// start of an entry's, as an index line shows it, and the store resolves it
/// within its stream (`keys.list`'s `prefix`): one that begins no key, or
/// more than one, is refused, naming the full handles it could mean, so a
/// read never guesses.
export async function resolveHandle(ctx, { entry: { stream, key, version } }) {
  const named = (full) => ({ handle: handleOf(stream, full, version), stream, key: full, after_version: version - 1 });
  if (!SHORT_KEY.test(key)) return named(key);
  const listed = await resultOf(
    ctx,
    await ctx.operation("private/keys.list", { stream, prefix: key, limit: SHORT_MATCHES }),
  );
  const keys = (listed?.keys ?? []).map((item) => item.key);
  if (keys.length === 1) return named(keys[0]);
  const handle = handleOf(stream, key, version);
  if (keys.length === 0) throw new Error(`${handle} names no entry: no key on ${stream} begins ${key}`);
  const more = listed?.next_cursor ? ", and more" : "";
  throw new Error(
    `${handle} could mean ${keys.map((full) => handleOf(stream, full, version)).join(", ")}${more}: read one by its full handle`,
  );
}

/// What a purpose makes the person's words, as a gate says it.
const PURPOSES = {
  mandate: "a mandate, a rule every index shows",
  procedure: "a procedure, a rule every index shows",
  confirmed_memory: "something they told you",
};

/// When the content was true, and where it came from, as a gate says it.
function dated({ date, valid_until, sources }) {
  return `${date}${valid_until ? `, until ${valid_until}` : ""}, from ${sources.join(", ")}`;
}

const DESCRIBED = {
  "memory.remembered": ({ stream, data }) =>
    `Keep these exact words on ${stream}, as ${PURPOSES[data.purpose]}: "${data.text}" (${dated(data)}). The index shows them as: ${data.summary}`,
  "memory.corrected": ({ handle, data }) =>
    `Replace ${handle} with these exact words, as ${PURPOSES[data.purpose]}: "${data.text}" (${dated(data)}). The index shows them as: ${data.summary}`,
  "memory.disabled": ({ handle, data }) => `Stop ${handle} applying, because: ${data.reason}`,
  "memory.observed": ({ stream, handle, data }) =>
    `${handle ? `Supersede ${handle} with` : `Keep on ${stream}`} this observation: "${data.text}" (${dated(data)}). The index shows it as: ${data.summary}`,
};

/// Decide one write: refused unless the entry is where the write expects it,
/// and named by what a gate shows and the idempotency key the append carries.
/// Both cover the event's type, the version it follows and its content, its
/// end date and whether it stands as a rule among it, never the confirmation
/// the gate has yet to give. The person's words stand as a rule when their
/// purpose is a mandate or a procedure, which the append says as `standing`.
export function change({ entry, current, type, data, valid_until }) {
  const describe = DESCRIBED[type];
  if (!describe) throw new Error(`${type} is no memory event`);
  const at = current?.version ?? 0;
  const last = current?.last_event?.type;
  const handle = entry.version > 0 ? handleOf(entry.stream, entry.key, entry.version) : undefined;
  if (entry.version === 0 && at !== 0) {
    throw new Error(`these exact words are already kept, as ${handleOf(entry.stream, entry.key, at)}`);
  }
  if (entry.version > 0 && at !== entry.version) {
    throw new Error(
      at === 0
        ? `${handle} names no entry that's kept`
        : `${handle} isn't current: the entry is at version ${at}, as ${handleOf(entry.stream, entry.key, at)}`,
    );
  }
  if (last === "memory.disabled") {
    throw new Error(`${handle} is disabled, and a disabled entry doesn't change`);
  }
  if (type === "memory.observed" && entry.version > 0 && last !== "memory.observed") {
    throw new Error(`${handle} isn't an observation, so an observation can't supersede it`);
  }
  if (valid_until !== undefined && data.date !== undefined && valid_until < data.date) {
    throw new Error(`it ends on ${valid_until}, before its own date, ${data.date}`);
  }
  const standing = STANDING.has(data.purpose);
  const content = Object.fromEntries(Object.entries(data).filter(([field]) => field !== "confirmation"));
  if (valid_until !== undefined) content.valid_until = valid_until;
  if (standing) content.standing = true;
  return {
    reason: describe({ stream: entry.stream, handle, data: content }),
    expected_version: at,
    idempotency_key: `memory:${sha256(JSON.stringify([type, entry.stream, entry.key, at, content]))}`,
    // Only the person's words have a purpose, which decides it.
    ...(data.purpose === undefined ? {} : { standing }),
  };
}

/// A new observation requires an empty key, proved by the append's compare
/// and swap. Superseding an observation also requires inspecting its current
/// status, under read authority; a write-only caller cannot supersede it.
export async function observationChange(ctx, { entry, data, valid_until }) {
  const current = entry.version > 0
    ? await resultOf(ctx, await ctx.operation("private/key.inspect", { stream: entry.stream, key: entry.key }))
    : undefined;
  return change({ entry, current, type: "memory.observed", data, valid_until });
}

/// The handle of a committed or replayed append. The native private driver
/// verifies the event under its idempotency key before returning this result.
/// An additional inspection, when supplied, must agree with that version.
export function entryHandle({ entry, appended, readback }) {
  const version = appended?.version;
  if (!["committed", "replayed"].includes(appended?.status) ||
      !appended?.event || version !== entry.version + 1 ||
      (readback !== undefined && readback !== null && readback.version !== version)) {
    throw new Error(`the append to ${entry.stream}#${entry.key} wasn't committed and verified at its expected version`);
  }
  return { handle: handleOf(entry.stream, entry.key, version) };
}

function length(text) {
  return [...text].length;
}

/// How many bytes `text` takes as UTF-8, with no copy of it: its UTF-16
/// length, one more for each character UTF-8 writes in two bytes, two more
/// for each it writes in three, and two more for each surrogate pair, whose
/// four bytes its length counts as two. JSON text holds no lone surrogate.
function bytes(text) {
  const count = (pattern) => text.match(pattern)?.length ?? 0;
  return (
    text.length +
    count(/[\u0080-\u07ff]/g) +
    2 * count(/[\u0800-\ud7ff\ue000-\uffff]/g) +
    2 * count(/[\ud800-\udbff]/g)
  );
}

/// The UTF-8 size of `data`'s JSON, `{"entries":[...]}`, counted an entry at
/// a time, so the whole is never built as one string.
function dataBytes({ entries }) {
  return entries.reduce(
    (sum, entry, at) => sum + bytes(JSON.stringify(entry)) + (at > 0 ? 1 : 0),
    bytes(JSON.stringify({ entries: [] })),
  );
}

/// The digest of `text`'s UTF-8 bytes, taken by the runtime (`data.digest`).
async function digestOf(ctx, text) {
  const { digest_result } = await ctx.tool("data.digest", { value: text, encoding: "utf8_text" });
  return digest_result.digest;
}

/// What a store event says of its entry, whole: its handle, its words and
/// line, its date and sources, the person's purpose for their words, and why
/// a disabled one stopped applying. The person's words read with their
/// purpose, and a disabled version of them, which holds none, as what the
/// person told you.
function dataOf({ stream, key, event }) {
  const kind = kindOf(stream);
  const data = {
    handle: handleOf(stream, key, event.version),
    kind,
    version: event.version,
    type: event.type,
    date: event.data?.date ?? null,
    text: event.data?.text ?? "",
    summary: event.data?.summary ?? null,
    sources: event.data?.sources ?? [],
  };
  if (kind === "said") data.purpose = purposeOf({ stream, event });
  if (event.valid_until) data.valid_until = event.valid_until;
  if (event.type === "memory.disabled") data.reason = event.data?.reason ?? null;
  return data;
}

/// The purpose a store event's entry reads to a turn with.
function purposeOf({ stream, event }) {
  if (kindOf(stream) === "observed") return "observation";
  return event.type === "memory.disabled" ? "confirmed_memory" : event.data?.purpose;
}

/// Where an entry came from: its sources, or its handle when it names none.
function sourcesOf(data) {
  return data.sources.length > 0 ? data.sources : [data.handle];
}

/// A store event as the context entry a turn reads, named by its full
/// handle: a line, `<handle> <date> <summary>`, the entry whole as its data,
/// and the labels its kind gives it.
function entryOf({ stream, key, event, method }) {
  const kind = kindOf(stream);
  const data = dataOf({ stream, key, event });
  const { handle, text } = data;
  return {
    schema: SCHEMA,
    type: `memory.${kind}`,
    summary: line({ handle, date: data.date, summary: data.summary }),
    data,
    labels: { purpose: purposeOf({ stream, event }), trust: KINDS[kind].trust, sharing: "configured_model" },
    sources: sourcesOf(data),
    origin: {
      artifact_id: handle,
      step_id: null,
      producer: { skill: SKILL, method },
      created_at: event.committed_at,
      digest: `sha256:${sha256(text)}`,
      size_bytes: utf8(text).length,
    },
  };
}

/// An index line: `<handle> <date>`, and its summary after when it has one.
function line({ handle, date, summary }) {
  const head = `${handle} ${date ?? "undated"}`;
  return summary ? `${head} ${summary}` : head;
}

/// The entry a read of one version returned, whether or not it's current.
export function contextEntry({ handle, read }) {
  const { stream, key, version } = parsed(handle);
  const event = (read?.events ?? []).find((candidate) => candidate.version === version);
  if (!event) throw new Error(`${handle} names no version that's kept`);
  return { entry: entryOf({ stream, key, event, method: "read" }) };
}

/// The streams `levels` names, the person's words before observations, each
/// once, passing over a level that needs a workspace this run doesn't have.
function streamsOf(levels, workspace_id) {
  const streams = { said: [], observed: [] };
  for (const kind of Object.keys(KINDS)) {
    for (const level of levels) {
      if (level.level !== "personal" && (workspace_id === null || workspace_id === undefined)) continue;
      const stream = streamOf(kind, { ...level, workspace_id });
      if (!streams[kind].includes(stream)) streams[kind].push(stream);
    }
  }
  return streams;
}

/// A store call's result, as its operation packet holds it. A packet past
/// the inline bound reaches the script as a reference to the artifact the
/// call recorded it in, and `ctx.read` reads it whole, as it gives an inline
/// one back as it is: a page of keys, whatever its size, is never read as
/// empty.
async function resultOf(ctx, value) {
  return (await ctx.read(value?.provider_operation))?.result;
}

/// Whether a call was refused admission: a stream the run's authority
/// doesn't reach is passed over, never an error.
function refused(error) {
  return error?.code === "refused";
}

/// How many keys a page asks a stream for, with `room` characters left.
function pageKeysFor(room) {
  return Math.max(1, Math.min(MAX_PAGE_KEYS, Math.ceil(room / SHORTEST_LINE)));
}

/// One stream's keys, newest commit first, a page at a time, as `query`
/// selects them, each page `pageKeys()` keys. A stream the run's authority
/// doesn't reach reads as empty.
class StreamPages {
  constructor(ctx, stream, query, pageKeys) {
    Object.assign(this, { ctx, stream, query, pageKeys, keys: [], cursor: undefined, done: false });
  }

  async head() {
    if (this.keys.length === 0 && !this.done) {
      try {
        const page = await resultOf(
          this.ctx,
          await this.ctx.operation("private/keys.list", {
            stream: this.stream,
            ...this.query,
            limit: this.pageKeys(),
            ...(this.cursor ? { cursor: this.cursor } : {}),
          }),
        );
        this.keys = page?.keys ?? [];
        this.cursor = page?.next_cursor ?? undefined;
        this.done = !this.cursor;
      } catch (error) {
        if (!refused(error)) throw error;
        this.keys = [];
        this.done = true;
      }
    }
    return this.keys[0];
  }

  take() {
    return this.keys.shift();
  }
}

/// The newer of two keys, as each stream lists them: newest commit first,
/// ties by key, then by the stream the levels name first.
function newer(left, right) {
  const at = (item) => item.last_event.committed_at;
  if (at(left) !== at(right)) return at(left) > at(right);
  return left.key < right.key;
}

/// Every key of `pages` newest first, merged across their streams, each
/// handed to `take` until it says stop.
async function walk(pages, take) {
  for (;;) {
    let from;
    for (const candidate of pages) {
      const head = await candidate.head();
      if (head && (!from || newer(head, await from.head()))) from = candidate;
    }
    if (!from) return;
    const head = from.take();
    if (!(await take(from.stream, head))) return;
  }
}

/// The date `ctx.now()` reads, `YYYY-MM-DD`, in UTC.
function today(ctx) {
  return new Date(ctx.now()).toISOString().slice(0, 10);
}

/// How many characters two keys start with alike.
function sharedStart(left, right) {
  let at = 0;
  while (at < left.length && at < right.length && left[at] === right[at]) at += 1;
  return at;
}

/// An index's lines under their headers: one group per stream and purpose,
/// each line `<key>@<version> <date> <summary>`, and the characters the
/// groups' summaries hold. A line's key is the shortest start of its entry's,
/// at least [`SHORTEST_KEY`] characters, that no other line of its stream
/// shares, so its header and the line make a short handle `read` resolves.
class Lines {
  constructor() {
    // Each stream's lines in key order, so a key's longest shared start is
    // with a neighbour, and weighing a line costs no walk of its stream.
    Object.assign(this, { groups: [], used: 0, sorted: new Map() });
  }

  /// The line `item` shows, whole or without its summary.
  static text({ key, event, keyLength, whole }) {
    const head = `${key.slice(0, keyLength)}@${event.version} ${event.data?.date ?? "undated"}`;
    return whole && event.data?.summary ? `${head} ${event.data.summary}` : head;
  }

  /// Where `key` goes among `stream`'s lines in key order, and the lines
  /// either side of it: the only ones that can share its longest start, since
  /// any other shares no more with it than with the neighbour between them.
  neighbours(stream, key) {
    const lines = this.sorted.get(stream) ?? [];
    let low = 0;
    let high = lines.length;
    while (low < high) {
      const middle = (low + high) >> 1;
      if (lines[middle].key < key) low = middle + 1;
      else high = middle;
    }
    return { at: low, peers: [lines[low - 1], lines[low]].filter(Boolean) };
  }

  /// What showing `item` whole adds: its line, its group's header when the
  /// group is new, and what its neighbours' keys grow by to stay apart from
  /// it. With the key it would show.
  cost({ stream, purpose, key, event }) {
    let keyLength = SHORTEST_KEY;
    let grows = 0;
    for (const peer of this.neighbours(stream, key).peers) {
      const shared = sharedStart(key, peer.key);
      keyLength = Math.max(keyLength, shared + 1);
      grows += Math.max(0, shared + 1 - peer.keyLength);
    }
    const group = this.groups.find((candidate) => candidate.stream === stream && candidate.purpose === purpose);
    const header = group ? 0 : length(`memory:${stream}`);
    const line = length(Lines.text({ key, event, keyLength, whole: true }));
    return { characters: header + 1 + line + grows, keyLength };
  }

  /// Show `item` whole, after the lines its group already shows, and return
  /// its line.
  add(item) {
    const { characters, keyLength } = this.cost(item);
    const { at, peers } = this.neighbours(item.stream, item.key);
    for (const peer of peers) {
      peer.keyLength = Math.max(peer.keyLength, sharedStart(item.key, peer.key) + 1);
    }
    let group = this.groups.find((candidate) => candidate.stream === item.stream && candidate.purpose === item.purpose);
    if (!group) {
      group = { stream: item.stream, purpose: item.purpose, items: [] };
      this.groups.push(group);
    }
    const line = { ...item, keyLength, whole: true };
    group.items.push(line);
    if (!this.sorted.has(item.stream)) this.sorted.set(item.stream, []);
    this.sorted.get(item.stream).splice(at, 0, line);
    this.used += characters;
    return line;
  }

  /// Take `item`'s summary from its line, as a rule loses it past the budget.
  bare(item) {
    if (!item.whole || !item.event.data?.summary) return;
    this.used -= length(Lines.text(item)) - length(Lines.text({ ...item, whole: false }));
    item.whole = false;
  }

  /// Each group as one context entry: its header and lines as its summary,
  /// its entries whole as its data, labelled with its stream's trust and its
  /// purpose.
  async entries(ctx) {
    const entries = [];
    for (const { stream, purpose, items } of this.groups) {
      const kind = kindOf(stream);
      const header = `memory:${stream}`;
      const data = { entries: items.map(({ key, event }) => dataOf({ stream, key, event })) };
      const summary = [header, ...items.map(Lines.text)].join("\n");
      entries.push({
        schema: SCHEMA,
        type: `memory.${kind}`,
        summary,
        data,
        labels: { purpose, trust: KINDS[kind].trust, sharing: "configured_model" },
        sources: [...new Set(data.entries.flatMap(sourcesOf))],
        origin: {
          artifact_id: header,
          step_id: null,
          producer: { skill: SKILL, method: "index" },
          created_at: items.map(({ event }) => event.committed_at).reduce((newest, at) => (at > newest ? at : newest)),
          // What it says, as a single entry's digest is its words': each
          // line names its entry's key and version.
          digest: await digestOf(ctx, summary),
          size_bytes: dataBytes(data),
        },
      });
    }
    return entries;
  }
}

/// A bounded index for a turn: one context entry per stream and purpose, its
/// summary a header, `memory:<stream>`, and a line per entry (see [`Lines`]).
/// The person's standing rules first, every one, oldest first, read from the
/// standing keys apart, so the facts' walk never visits one. Then facts, the
/// person's other words before observations: with a focus, those its search
/// matches first, best first and newest first among equals, and the rest
/// newest first; without one, newest first. An entry whose end date has
/// passed by the run's clock is passed over by the store, never read and
/// dropped here.
///
/// Every line holds its summary. Facts fill the room the rules leave whole,
/// in rank order, read page by page and no further than the last line that
/// could fit, and the first that doesn't fit ends them. A rule's line never
/// goes: when the rules alone pass the budget, no fact shows, the rules'
/// summaries go, newest first, which keeps the request's prefix, and the index
/// says so. It says when it cut entries, which search and read reach, and
/// counts nothing.
export async function index(ctx, { levels, max_characters = 4096, focus, workspace_id }) {
  const streams = streamsOf(levels, workspace_id);
  const valid_at = today(ctx);
  const budget = max_characters;
  const shown = new Lines();
  const rules = [];
  for (const [order, stream] of streams.said.entries()) {
    const pages = new StreamPages(
      ctx,
      stream,
      { types: KINDS.said.types, standing: true, valid_at },
      () => MAX_PAGE_KEYS,
    );
    await walk([pages], (_, listed) => {
      rules.push({ stream, order, key: listed.key, event: listed.last_event });
      return true;
    });
  }
  rules.sort(
    (left, right) =>
      (left.event.committed_at < right.event.committed_at ? -1 : left.event.committed_at > right.event.committed_at ? 1 : 0) ||
      (left.key < right.key ? -1 : left.key > right.key ? 1 : 0) ||
      left.order - right.order,
  );
  const ruleLines = rules.map(({ stream, key, event }) =>
    shown.add({ stream, key, event, purpose: purposeOf({ stream, event }) }),
  );
  // Facts get only the room the rules leave whole, so no fact takes the
  // room a rule's summary needed.
  const over_budget = shown.used > budget;
  let omitted = false;
  const seen = new Set();
  const room = () => budget - shown.used;
  // A fact's line whole while it fits; the first that doesn't ends the facts.
  const fact = (stream, key, event) => {
    const item = { stream, key, event, purpose: purposeOf({ stream, event }) };
    if (shown.cost(item).characters > room()) {
      omitted = true;
      return false;
    }
    shown.add(item);
    seen.add(`${stream}#${key}`);
    return true;
  };
  for (const kind of Object.keys(KINDS)) {
    const query = { types: KINDS[kind].types, standing: false, valid_at };
    if (focus) {
      const matched = [];
      for (const [order, stream] of streams[kind].entries()) {
        try {
          const page = await resultOf(
            ctx,
            await ctx.operation("private/keys.search", { stream, query: focus, ...query, limit: pageKeysFor(room()) }),
          );
          for (const match of page?.matches ?? []) matched.push({ stream, order, ...match });
        } catch (error) {
          if (!refused(error)) throw error;
        }
      }
      matched.sort(
        (left, right) =>
          right.score - left.score ||
          (left.last_event.committed_at > right.last_event.committed_at ? -1 : left.last_event.committed_at < right.last_event.committed_at ? 1 : 0) ||
          (left.key < right.key ? -1 : left.key > right.key ? 1 : 0) ||
          left.order - right.order,
      );
      for (const match of matched) {
        if (!fact(match.stream, match.key, match.last_event)) break;
      }
    }
    if (omitted) break;
    const pages = streams[kind].map((stream) => new StreamPages(ctx, stream, query, () => pageKeysFor(room())));
    await walk(pages, (stream, listed) =>
      seen.has(`${stream}#${listed.key}`) ? true : fact(stream, listed.key, listed.last_event),
    );
    if (omitted) break;
  }
  // Rules past the budget lose their summaries newest first.
  for (let at = ruleLines.length - 1; at >= 0 && shown.used > budget; at -= 1) shown.bare(ruleLines[at]);
  return { entries: await shown.entries(ctx), entries_omitted: omitted, over_budget };
}

/// Ranked matches among the current entries of the streams the run may
/// read: one search of each stream, merged by score, a person's words before
/// an observation, then newest first, then by key.
export async function search(ctx, { levels, query, limit = 10, workspace_id }) {
  const streams = streamsOf(levels, workspace_id);
  const found = [];
  for (const kind of Object.keys(KINDS)) {
    for (const stream of streams[kind]) {
      try {
        const result = await resultOf(
          ctx,
          await ctx.operation("private/keys.search", {
            stream,
            query,
            types: KINDS[kind].types,
            limit,
          }),
        );
        for (const match of result?.matches ?? []) found.push({ kind, stream, ...match });
      } catch (error) {
        if (!refused(error)) throw error;
      }
    }
  }
  const rank = { said: 0, observed: 1 };
  found.sort(
    (left, right) =>
      right.score - left.score ||
      rank[left.kind] - rank[right.kind] ||
      (left.last_event.committed_at > right.last_event.committed_at
        ? -1
        : left.last_event.committed_at < right.last_event.committed_at
          ? 1
          : 0) ||
      (left.key < right.key ? -1 : left.key > right.key ? 1 : 0) ||
      (left.stream < right.stream ? -1 : left.stream > right.stream ? 1 : 0),
  );
  return {
    entries: found
      .slice(0, limit)
      .map(({ stream, key, last_event }) => entryOf({ stream, key, event: last_event, method: "search" })),
  };
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://schemas.runx.ai/packages/runx/memory/entries/v1.json",
  "x-runx-packet-id": "runx/memory.entries.v1",
  "title": "Memory entries",
